fetch() { for i in 1 2 3 4; do out=$(curl -s "$1"); if echo "$out" | head -c 1 | grep -q '{'; then echo "$out"; return; fi; sleep 8; done; echo '{}'; }
for a in "Justin+Hilburn" "Scott+Kilpatrick" "David+Chase" "Karl+Naden"; do echo "== $a =="; fetch "https://dblp.org/search/author/api?q=$a&format=json&h=10" | python3 -c "
import json,sys
try: d=json.load(sys.stdin); hits=d['result']['hits']
except: print('ERR'); sys.exit()
for h in hits.get('hit',[]):
    i=h['info']; print('-',i.get('author'),'|',i.get('url'))
"; sleep 6; done

fetchx() { for i in 1 2 3 4; do out=$(curl -s "$1"); if echo "$out" | head -c 5 | grep -q '<'; then echo "$out"; return; fi; sleep 8; done; }
echo "== Steele 2009-2016 =="; fetchx "https://dblp.org/pid/s/GuyLSteeleJr.xml" | python3 -c "
import sys,xml.etree.ElementTree as ET
t=ET.fromstring(sys.stdin.read())
for r in t.iter():
    if r.tag in ('article','inproceedings','incollection'):
        y=r.findtext('year')
        if y and 2009<=int(y)<=2016:
            venue=r.findtext('journal') or r.findtext('booktitle') or ''
            print(f'- {r.findtext(\"title\")} | {venue} {y} | key={r.get(\"key\")}')
"

fetchj() { for i in 1 2 3 4; do out=$(curl -s "$1"); if echo "$out" | head -c 1 | grep -q '{'; then echo "$out"; return; fi; sleep 8; done; echo '{}'; }
fetchj "https://dblp.org/search/author/api?q=Sukyoung+Ryu&format=json&h=5" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for h in d['result']['hits'].get('hit',[]): print(h['info'].get('author'), h['info'].get('url'))
"

fetchx() { for i in 1 2 3 4; do out=$(curl -s "$1"); if echo "$out" | head -c 5 | grep -q '<'; then echo "$out"; return; fi; sleep 8; done; }
fetchx "https://dblp.org/pid/03/2760.xml" | python3 -c "
import sys,re,xml.etree.ElementTree as ET
t=ET.fromstring(sys.stdin.read())
pat=re.compile(r'fortress|dispatch|generic|inherit|multimethod|type.?check|variance|return type',re.I)
for r in t.iter():
    if r.tag in ('article','inproceedings','incollection'):
        title=r.findtext('title') or ''
        if pat.search(title):
            venue=r.findtext('journal') or r.findtext('booktitle') or ''
            auth=', '.join(a.text for a in r.findall('author'))
            print(f'- {title} | {venue} {r.findtext(\"year\")} | {auth} | key={r.get(\"key\")}')
"

